import http from 'node:http';
import { URL } from 'node:url';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { open } from 'node:sqlite';
import sqlite3 from 'node:sqlite3';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PORT = process.env.PORT ? Number(process.env.PORT) : 8080;
const DB_PATH = process.env.DB_PATH || path.join(__dirname, 'workboard.db');

const dbPromise = (async () => {
  const db = await open({ filename: DB_PATH, driver: sqlite3.Database });
  await db.run(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)`);
  return db;
})();

async function serveStatic(filePath, res) {
  try {
    const data = await readFile(filePath);
    const ext = path.extname(filePath).toLowerCase();
    const ct = {
      '.html': 'text/html',
      '.js': 'application/javascript',
      '.css': 'text/css'
    }[ext] || 'application/octet-stream';
    res.writeHead(200, { 'Content-Type': ct });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('Not found');
  }
}

async function parseJson(req) {
  const chunks = [];
  for await (const chunk of req) { chunks.push(chunk); }
  const body = Buffer.concat(chunks).toString();
  return JSON.parse(body);
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const pathname = url.pathname;

  if (pathname === '/health' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }

  if (pathname.startsWith('/api/')) {
    const db = await dbPromise;
    // List projects
    if (pathname === '/api/projects' && req.method === 'GET') {
      const rows = await db.all('SELECT id, name FROM projects ORDER BY id ASC');
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(rows));
      return;
    }
    // Create project
    if (pathname === '/api/projects' && req.method === 'POST') {
      try {
        const { name } = await parseJson(req);
        const trimmed = typeof name === 'string' ? name.trim() : '';
        if (!trimmed) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Project name is required' }));
          return;
        }
        const result = await db.run('INSERT INTO projects (name) VALUES (?)', trimmed);
        const newProject = { id: result.lastID, name: trimmed };
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(newProject));
      } catch (e) {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Internal server error' }));
      }
      return;
    }
    // Get single project
    const match = pathname.match(/^\/api\/projects\/(\d+)$/);
    if (match && req.method === 'GET') {
      const id = Number(match[1]);
      const row = await db.get('SELECT id, name FROM projects WHERE id = ?', id);
      if (!row) {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Project not found' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(row));
      return;
    }
    res.writeHead(404);
    res.end('Not found');
    return;
  }

  // Serve SPA for root and project pages
  if (pathname === '/' || pathname.startsWith('/projects/')) {
    await serveStatic(path.join(__dirname, 'public', 'index.html'), res);
    return;
  }

  // Serve static assets (if any)
  if (pathname.startsWith('/static/')) {
    const assetPath = path.join(__dirname, 'public', pathname.replace(/^\/static\//, ''));
    await serveStatic(assetPath, res);
    return;
  }

  res.writeHead(404);
  res.end('Not found');
});

server.listen(PORT, '0.0.0.0', () => {
  console.log(`Server listening on http://0.0.0.0:${PORT}`);
});
